('an_l1','animals','lesson','أصوات الحيوانات','1f436',array['a2','a3']::text[],1,$j${"goal": "أتعرف على بعض الحيوانات وأصواتها.", "pages": [{"t": "الكلب يقول هاو هاو.", "img": "1f436", "k": "explain"}, {"t": "القطة تقول مياو.", "img": "1f431", "k": "explain"}, {"t": "البقرة تقول موو. قلها معنا!", "img": "1f404", "k": "example"}], "check": {"q": "ماذا تقول القطة؟", "o": ["مياو", "هاو هاو", "موو"], "a": 0, "why": "القطة تقول مياو."}}$j$::jsonb,null,'كُتب النشاط برمجيا بصياغة مبسطة مناسبة للعمر، وفُحصت بنيته آليا (الإجابات والخيارات والأحرف والرسوم)، وراجعه المنفذ لدقة معلوماته الأساسية دون مراجعة مختص تعليمي. المطلوب مراجعة مختص قبل الاعتماد النهائي.',true,'published',1),
